167	@Service
168	@RequiredArgsConstructor
169	@Slf4j
170	public class OrderCommandService {
171	
172	    private final OrderRepository orderRepository;
173	    private final PaymentCommandService paymentCommandService;
174	    private final OrderShipmentCommandService orderShipmentCommandService;
175	    private final OrderItemCommandService orderItemCommandService;
176	    private final OrderBidQueryService orderBidQueryService;
177	    private final UserQueryService userQueryService;
178	    private final WarehouseStorageCommandService warehouseStorageCommandService;
179	    private final AddressQueryService addressQueryService;
180	    private final EntityManager entityManager;
181	
182	    /**
183	     * 입찰에서 주문을 생성합니다.
184	     *
185	     * @param user 사용자 정보
186	     * @param productSize 상품 사이즈 정보
187	     * @param bidPrice 입찰 가격
188	     * @return 생성된 주문
189	     * @throws OrderCreationFailedException 주문 생성 실패 시
190	     * @throws InvalidBidPriceException 입찰 가격이 유효하지 않을 경우
191	     */
192	    @Transactional
193	    public Order createOrderFromBid(User user, ProductSize productSize, int bidPrice) {
194	        try {
195	            // 입력값 검증
196	            if (user == null) {
197	                throw new InvalidOrderDataException("사용자 정보가 없습니다.");
198	            }
199	            if (productSize == null) {
200	                throw new ProductSizeNotFoundException("상품 사이즈 정보가 없습니다.");
201	            }
202	            if (bidPrice <= 0) {
203	                throw new InvalidBidPriceException("입찰 가격은 0보다 커야 합니다. 현재 가격: " + bidPrice);
204	            }
205	
206	            // 1. OrderItem 생성
207	            OrderItem orderItem = orderItemCommandService.createOrderItem(null, productSize, bidPrice);
208	
209	            // 2. Order 생성
210	            Order order = Order.builder()
211	                    .user(user)
212	                    .totalAmount(bidPrice) // 입찰가를 총 금액으로 설정
213	                    .discountAmount(0) // 초기값은 0
214	                    .usedPoints(0) // 초기값은 0
215	                    .status(OrderStatus.PENDING_PAYMENT) // 결제 대기 상태
216	                    .build();
217	
218	            // 3. OrderItem과 연관 설정
219	            order.addOrderItem(orderItem);
220	
221	            // 4. Order 저장
222	            return orderRepository.save(order);
223	        } catch (Exception e) {
224	            if (e instanceof OrderException) {
225	                throw e;
226	            }
227	            log.error("주문 생성 중 오류 발생: {}", e.getMessage(), e);
228	            throw new OrderCreationFailedException("입찰에서 주문 생성 중 오류가 발생했습니다: " + e.getMessage(), e);
229	        }
230	    }
231	
232	    /**
233	     * 주문에 대한 결제 및 배송 정보를 처리합니다.
234	     *
235	     * @param orderId 주문 ID
236	     * @param userEmail 사용자 이메일
237	     * @param requestDto 결제 및 배송 요청 정보
238	     * @throws OrderNotFoundException 주문을 찾을 수 없는 경우
239	     * @throws OrderAccessDeniedException 주문에 대한 접근 권한이 없는 경우
240	     * @throws OrderPaymentProcessingFailedException 결제 처리 실패 시
241	     * @throws OrderShipmentProcessingFailedException 배송 처리 실패 시
242	     * @throws OrderWarehouseStorageProcessingFailedException 창고 보관 처리 실패 시
243	     * @throws InvalidPaymentShipmentDataException 결제 및 배송 정보가 유효하지 않은 경우
244	     */
245	    @Transactional
246	    public void processPaymentAndShipment(Long orderId, String userEmail, PayAndShipmentRequestDto requestDto) {
247	        if (orderId == null) {
248	            throw new InvalidOrderDataException("주문 ID가 없습니다.");
249	        }
250	        if (userEmail == null || userEmail.trim().isEmpty()) {
251	            throw new OrderAccessDeniedException("사용자 정보가 없습니다.");
252	        }
253	        if (requestDto == null) {
254	            throw new InvalidPaymentShipmentDataException("결제 및 배송 정보가 없습니다.");
255	        }
256	
257	        try {
258	            // 1. User 및 Order 조회
259	            User user = userQueryService.findByEmail(userEmail);
260	            Order order = orderRepository.findById(orderId)
261	                    .orElseThrow(() -> new OrderNotFoundException("해당 주문을 찾을 수 없습니다(ID: " + orderId + ")"));
262	
263	            // 접근 권한 확인
264	            if (!order.getUser().getId().equals(user.getId())) {
265	                throw new OrderAccessDeniedException("해당 사용자는 이 주문을 처리할 권한이 없습니다.");
266	            }
267	
268	            // 주문 정보 유효성 검사
269	            validatePaymentShipmentRequest(requestDto);
270	
271	            try {
272	                // 2. 결제 처리
273	                Payment payment = paymentCommandService.processPayment(order, user, requestDto.getPaymentRequest());
274	                order.assignPayment(payment);
275	            } catch (Exception e) {
276	                log.error("결제 처리 중 오류 발생: {}", e.getMessage(), e);
277	                throw new OrderPaymentProcessingFailedException("결제 처리 중 오류가 발생했습니다: " + e.getMessage(), e);
278	            }
279	
280	            try {
281	                // 3. 배송 정보 생성
282	                OrderShipment shipment = orderShipmentCommandService.createOrderShipment(
283	                        order,
284	                        requestDto.getReceiverName(),
285	                        requestDto.getReceiverPhone(),
286	                        requestDto.getPostalCode(),
287	                        requestDto.getAddress()
288	                );
289	                order.assignOrderShipment(shipment);
290	            } catch (Exception e) {
291	                log.error("배송 정보 처리 중 오류 발생: {}", e.getMessage(), e);
292	                throw new OrderShipmentProcessingFailedException("배송 정보 처리 중 오류가 발생했습니다: " + e.getMessage(), e);
293	            }
294	
295	            try {
296	                // 4. 상태 업데이트
297	                if (requestDto.isWarehouseStorage()) {
298	                    // 창고 보관일 경우
299	                    order.updateStatus(OrderStatus.PAYMENT_COMPLETED);
300	                    order.updateStatus(OrderStatus.PREPARING);
301	                    order.updateStatus(OrderStatus.IN_WAREHOUSE);
302	
303	                    // 창고 보관 처리 추가
304	                    WarehouseStorage warehouseStorage = warehouseStorageCommandService.createOrderStorage(order, user);
305	                    order.assignWarehouseStorage(warehouseStorage);
306	                    order.updateStatus(OrderStatus.COMPLETED);  // 주문 완료 상태로 변경
307	                } else {
308	                    // 실제 배송일 경우
309	                    order.updateStatus(OrderStatus.PAYMENT_COMPLETED);
310	                    order.updateStatus(OrderStatus.PREPARING);
311	                }
312	            } catch (WarehouseStorageException e) {
313	                log.error("창고 보관 처리 중 오류 발생: {}", e.getMessage(), e);
314	                throw new OrderWarehouseStorageProcessingFailedException("창고 보관 처리 중 오류가 발생했습니다: " + e.getMessage(), e);
315	            } catch (Exception e) {
316	                log.error("주문 상태 업데이트 중 오류 발생: {}", e.getMessage(), e);
317	                throw new OrderStatusUpdateFailedException("주문 상태 업데이트 중 오류가 발생했습니다: " + e.getMessage(), e);
318	            }
319	
320	            // 5. OrderBid 상태 업데이트
321	            try {
322	                orderBidQueryService.findById(orderId).ifPresent(orderBid -> {
323	                    orderBid.updateStatus(BidStatus.MATCHED);
324	                });
325	            } catch (Exception e) {
326	                log.error("주문 입찰 상태 업데이트 중 오류 발생: {}", e.getMessage(), e);
327	                // 중요 정보 처리가 완료되었으므로 예외를 던지지 않고 로그만 남김
328	            }
329	        } catch (Exception e) {
330	            if (e instanceof OrderException) {
331	                throw e;
332	            }
333	            log.error("결제 및 배송 처리 중 오류 발생: {}", e.getMessage(), e);
334	            throw new OrderPaymentProcessingFailedException("결제 및 배송 처리 중 예상치 못한 오류가 발생했습니다: " + e.getMessage(), e);
335	        }
336	    }
337	
338	    /**
339	     * 즉시 구매 주문을 생성합니다.
340	     *
341	     * @param buyer 구매자 정보
342	     * @param saleBid 판매 입찰 정보
343	     * @param addressId 배송지 ID
344	     * @param isWarehouseStorage 창고 보관 여부
345	     * @param paymentRequest 결제 요청 정보
346	     * @return 생성된 주문
347	     * @throws OrderCreationFailedException 주문 생성 실패 시
348	     * @throws SaleBidNotFoundException 판매 입찰을 찾을 수 없는 경우
349	     * @throws InvalidOrderDataException 주문 정보가 유효하지 않은 경우
350	     * @throws OrderPaymentProcessingFailedException 결제 처리 실패 시
351	     * @throws OrderWarehouseStorageProcessingFailedException 창고 보관 처리 실패 시
352	     */
353	    @Transactional
354	    public Order createInstantOrder(User buyer, SaleBid saleBid, Long addressId,
355	                                    boolean isWarehouseStorage, PaymentRequestDto paymentRequest) {
356	        try {
357	            // 입력값 검증
358	            if (buyer == null) {
359	                throw new InvalidOrderDataException("구매자 정보가 없습니다.");
360	            }
361	            if (saleBid == null) {
362	                throw new SaleBidNotFoundException("판매 입찰 정보가 없습니다.");
363	            }
364	            if (addressId == null) {
365	                throw new InvalidOrderDataException("배송지 정보가 없습니다.");
366	            }
367	            if (paymentRequest == null) {
368	                throw new InvalidPaymentShipmentDataException("결제 정보가 없습니다.");
369	            }
370	
371	            // 1. 주소 조회
372	            AddressResponseDto address = addressQueryService.getAddress(buyer.getEmail(), addressId);
373	
374	            // 2. Order 생성
375	            Order order = Order.builder()
376	                    .user(buyer)
377	                    .totalAmount(saleBid.getBidPrice())
378	                    .status(OrderStatus.PENDING_PAYMENT)
379	                    .build();
380	
381	            order = orderRepository.save(order);
382	
383	            // PaymentRequest에 OrderId 설정
384	            paymentRequest.setOrderId(order.getId());
385	            log.debug("결제 요청 정보: {}", paymentRequest);
386	
387	            // 3. OrderItem 추가
388	            try {
389	                OrderItem orderItem = orderItemCommandService.createOrderItem(order, saleBid.getProductSize(), saleBid.getBidPrice());
390	                order.addOrderItem(orderItem);
391	            } catch (Exception e) {
392	                log.error("주문 항목 생성 중 오류 발생: {}", e.getMessage(), e);
393	                throw new OrderItemCreationFailedException("주문 항목 생성 중 오류가 발생했습니다: " + e.getMessage(), e);
394	            }
395	
396	            // 4. 배송 정보 생성 및 연관 설정
397	            try {
398	                OrderShipment orderShipment = orderShipmentCommandService.createOrderShipment(
399	                        order,
400	                        address.getRecipientName(),
401	                        address.getPhoneNumber(),
402	                        address.getZipCode(),
403	                        address.getAddress()
404	                );
405	                order.assignOrderShipment(orderShipment);
406	            } catch (Exception e) {
407	                log.error("배송 정보 생성 중 오류 발생: {}", e.getMessage(), e);
