302	
303	                    // 창고 보관 처리 추가
304	                    WarehouseStorage warehouseStorage = warehouseStorageCommandService.createOrderStorage(order, user);
305	                    order.assignWarehouseStorage(warehouseStorage);
306	                    order.updateStatus(OrderStatus.COMPLETED);  // 주문 완료 상태로 변경
307	                } else {
