310	                    order.updateStatus(OrderStatus.PREPARING);
311	                }
312	            } catch (WarehouseStorageException e) {
313	                log.error("창고 보관 처리 중 오류 발생: {}", e.getMessage(), e);
314	                throw new OrderWarehouseStorageProcessingFailedException("창고 보관 처리 중 오류가 발생했습니다: " + e.getMessage(), e);
315	            } catch (Exception e) {
