352	     */
353	    @Transactional
354	    public Order createInstantOrder(User buyer, SaleBid saleBid, Long addressId,
355	                                    boolean isWarehouseStorage, PaymentRequestDto paymentRequest) {
356	        try {
357	            // 입력값 검증
358	            if (buyer == null) {
359	                throw new InvalidOrderDataException("구매자 정보가 없습니다.");
360	            }
361	            if (saleBid == null) {
362	                throw new SaleBidNotFoundException("판매 입찰 정보가 없습니다.");
363	            }
364	            if (addressId == null) {
365	                throw new InvalidOrderDataException("배송지 정보가 없습니다.");
366	            }
367	            if (paymentRequest == null) {
368	                throw new InvalidPaymentShipmentDataException("결제 정보가 없습니다.");
369	            }
370	
371	            // 1. 주소 조회
372	            AddressResponseDto address = addressQueryService.getAddress(buyer.getEmail(), addressId);
373	
374	            // 2. Order 생성
375	            Order order = Order.builder()
376	                    .user(buyer)
377	                    .totalAmount(saleBid.getBidPrice())
378	                    .status(OrderStatus.PENDING_PAYMENT)
379	                    .build();
380	
381	            order = orderRepository.save(order);
382	
383	            // PaymentRequest에 OrderId 설정
384	            paymentRequest.setOrderId(order.getId());
385	            log.debug("결제 요청 정보: {}", paymentRequest);
386	
387	            // 3. OrderItem 추가
388	            try {
389	                OrderItem orderItem = orderItemCommandService.createOrderItem(order, saleBid.getProductSize(), saleBid.getBidPrice());
390	                order.addOrderItem(orderItem);
391	            } catch (Exception e) {
392	                log.error("주문 항목 생성 중 오류 발생: {}", e.getMessage(), e);
393	                throw new OrderItemCreationFailedException("주문 항목 생성 중 오류가 발생했습니다: " + e.getMessage(), e);
394	            }
395	
396	            // 4. 배송 정보 생성 및 연관 설정
397	            try {
398	                OrderShipment orderShipment = orderShipmentCommandService.createOrderShipment(
399	                        order,
400	                        address.getRecipientName(),
401	                        address.getPhoneNumber(),
402	                        address.getZipCode(),
403	                        address.getAddress()
404	                );
405	                order.assignOrderShipment(orderShipment);
406	            } catch (Exception e) {
407	                log.error("배송 정보 생성 중 오류 발생: {}", e.getMessage(), e);
408	                throw new OrderShipmentProcessingFailedException("배송 정보 생성 중 오류가 발생했습니다: " + e.getMessage(), e);
409	            }
410	
411	            try {
412	                // 판매 입찰 상태 업데이트
413	                saleBid.assignOrder(order);
414	                saleBid.updateStatus(com.fream.back.domain.sale.entity.BidStatus.MATCHED);
415	
416	                // 변경 내용 강제 반영
417	                entityManager.flush();
418	            } catch (Exception e) {
419	                log.error("판매 입찰 상태 업데이트 중 오류 발생: {}", e.getMessage(), e);
420	                throw new OrderBidMatchingFailedException("판매 입찰 매칭 중 오류가 발생했습니다: " + e.getMessage(), e);
421	            }
422	
423	            // Sale의 isWarehouseStorage 확인 후 상태 변경
424	            try {
425	                Sale sale = saleBid.getSale();
426	                if (sale != null && sale.isWarehouseStorage()) {
427	                    warehouseStorageCommandService.updateWarehouseStatus(sale, WarehouseStatus.ASSOCIATED_WITH_ORDER);
428	                }
429	            } catch (WarehouseStorageException e) {
430	                log.error("창고 보관 상태 업데이트 중 오류 발생: {}", e.getMessage(), e);
431	                throw new OrderWarehouseStorageProcessingFailedException("창고 보관 상태 업데이트 중 오류가 발생했습니다: " + e.getMessage(), e);
432	            } catch (Exception e) {
433	                log.error("창고 보관 상태 업데이트 중 예상치 못한 오류 발생: {}", e.getMessage(), e);
434	                throw new OrderWarehouseStorageProcessingFailedException("창고 보관 상태 업데이트 중 예상치 못한 오류가 발생했습니다: " + e.getMessage(), e);
435	            }
436	
437	            // 결제 처리
438	            try {
439	                paymentCommandService.processPayment(order, buyer, paymentRequest);
440	            } catch (Exception e) {
441	                log.error("결제 처리 중 오류 발생: {}", e.getMessage(), e);
442	                throw new OrderPaymentProcessingFailedException("결제 처리 중 오류가 발생했습니다: " + e.getMessage(), e);
443	            }
444	
445	            return order;
446	        } catch (Exception e) {
447	            if (e instanceof OrderException) {
448	                throw e;
449	            }
450	            log.error("즉시 구매 주문 생성 중 오류 발생: {}", e.getMessage(), e);
451	            throw new OrderCreationFailedException("즉시 구매 주문 생성 중 오류가 발생했습니다: " + e.getMessage(), e);
452	        }
453	    }
