    99	            acknowledgment.acknowledge();
   100	
   101	            // 처리 시간 로깅
   102	            Instant end = Instant.now();
   103	            Duration duration = Duration.between(start, end);
   104	            log.info("주문 처리 완료 - 소요시간: {}ms, 주문ID={}", duration.toMillis(), event.getOrderId());
   105	
   106	        } catch (Exception e) {
